51	using ::sg::algorithms::sg11_phi_forward;
52	using ::sg::algorithms::sg11_adam_tail;
53	// NOTE: sg11_sweep_a_step / sg11_sweep_b_step were the per-element bodies of the
54	// two-sweep cosine-gate path (sg11_sweep_a_kernel / sg11_sweep_b_kernel /
55	// launch_supergrok11_step). That path was DEAD device code — no binding and no
56	// in-file caller launched launch_supergrok11_step (the live SG v1.1 path is
57	// launch_sg11_mu_metanet + compute_cosine_gate_fused + launch_sg11_adam_decay,
58	// orchestrated by supergrok11_fused_step in csrc/bindings/bindings.cpp). The
59	// sweep kernels + launcher are removed below, so these two using-declarations
60	// (which only fed them) are dropped as well. The canonical step bodies remain in
61	// csrc/algorithms/supergrok11.h, untouched.
62	
63	constexpr int SG11_H = 32;
64	
65	// Minimum resident blocks/SM for the element-wise sweeps. Caps registers so
66	// occupancy stays high on the (memory-bound) Adam apply.
67	#ifndef SG_TUNED_MIN_BLOCKS
68	#define SG_TUNED_MIN_BLOCKS 4
69	#endif
