71	// Cooperatively stage the per-element meta-net phi weights into shared memory
72	// ONCE per block, then hand the shared pointers to the canonical
73	// sg11_phi_forward<H>. W1 is [H,2] (row-major, 2 inputs/hidden unit), b1/W2 are
74	// [H]. The same weights are read by every element this block processes; staging
75	// removes the per-element re-read from GLOBAL inside the H-wide forward loop. NO
76	// math/signature change — the fn still takes const float* (single-sourced in
77	// algorithms/supergrok11.h).
78	template <int H>
79	__device__ __forceinline__ void sg11_stage_phi_weights(
80	    const float* __restrict__ W1, const float* __restrict__ b1,
81	    const float* __restrict__ W2,
82	    float* sW1, float* sb1, float* sW2
83	) {
84	    for (int j = threadIdx.x; j < H * 2; j += blockDim.x) sW1[j] = W1[j];
85	    for (int j = threadIdx.x; j < H;     j += blockDim.x) { sb1[j] = b1[j]; sW2[j] = W2[j]; }
86	    __syncthreads();
87	}
88	
89	// ── DEAD-CODE REMOVAL (SASS audit #5): SG v1.1 two-sweep cosine-gate path ──
90	//
91	// REMOVED here: sg11_sweep_a_kernel, sg11_sweep_b_kernel,
92	// sg11_sweep_b_kernel_vec4_fp32, and their sole host launcher
93	// launch_supergrok11_step.
94	//
95	// These were never-called device kernels. A whole-tree reference scan
96	// (csrc/bindings/bindings.cpp + all csrc + all Python) found ZERO references to
97	// any of the four C++ symbols outside this file, and no in-file caller launched
98	// launch_supergrok11_step. (The identically-named Python function in
99	// csrc/backends/pallas/launch_supergrok11.py is a separate JAX/Pallas symbol,
100	// not this CUDA launcher.)
101	//
102	// The LIVE SG v1.1 CUDA path is unchanged: launch_sg11_mu_metanet ->
103	// compute_cosine_gate_fused -> launch_sg11_adam_decay (plus launch_sg11_sam_-
104	// perturb / launch_sg11_sharpness_restore), orchestrated by
105	// supergrok11_fused_step in csrc/bindings/bindings.cpp. sg11_stage_phi_weights
106	// (used by the live sg11_mu_metanet_kernel) and the canonical per-element bodies
107	// in csrc/algorithms/supergrok11.h are untouched. This is removal of dead device
108	// code, NOT suppression of any reachable functionality.
109	
