182	void launch_sg11_adam_decay(
183	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
184	    torch::Tensor smart_grad, torch::Tensor mu,
185	    float lamb_eff, float beta1, float beta2, float lr,
186	    float wd_eff, float eps, float bc1, float bc2
187	) {
188	    const int64_t N = param.numel();
189	    if (N == 0) return;
190	    auto stream = at::cuda::getCurrentCUDAStream().stream();
191	    const int block = SG_TUNED_BLOCK_SIZE;
192	    const int grid = static_cast<int>(
193	        std::min<int64_t>(65535, (N + block - 1) / block));
194	    sg11_adam_decay_kernel<<<grid, block, 0, stream>>>(
195	        param.data_ptr<float>(), exp_avg.data_ptr<float>(),
196	        exp_avg_sq.data_ptr<float>(),
197	        smart_grad.data_ptr<float>(), mu.data_ptr<float>(),
198	        lamb_eff, beta1, beta2, lr, wd_eff, eps, bc1, bc2, N);
199	    SG_LAUNCH_CHECK(stream);
200	}
