202	// SAM perturbation: param += rho_over_norm * grad
203	template <typename ParamT>
204	__global__ void sg11_sam_perturb_kernel(
205	    ParamT* param, const ParamT* grad, float rho_over_norm, int64_t N
206	) {
207	    const int64_t stride = prim::grid_stride();
208	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
209	        float p = static_cast<float>(param[i]);
210	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
211	        param[i] = static_cast<ParamT>(p + rho_over_norm * g);
212	    }
213	}
214	
215	void launch_sg11_sam_perturb(
216	    torch::Tensor param, torch::Tensor grad, float rho_over_norm
217	) {
218	    const int64_t N = param.numel();
219	    if (N == 0) return;
220	    auto stream = at::cuda::getCurrentCUDAStream().stream();
221	    const int block = SG_TUNED_BLOCK_SIZE;
222	    const int grid = static_cast<int>(
223	        std::min<int64_t>(65535, (N + block - 1) / block));
224	    AT_DISPATCH_FLOATING_TYPES_AND2(
225	        at::ScalarType::Half, at::ScalarType::BFloat16,
226	        param.scalar_type(), "sg11_sam_perturb", [&] {
227	            sg11_sam_perturb_kernel<scalar_t><<<grid, block, 0, stream>>>(
228	                param.data_ptr<scalar_t>(), grad.data_ptr<scalar_t>(),
229	                rho_over_norm, N);
230	            SG_LAUNCH_CHECK(stream);
231	        });
232	}
