234	// Sharpness restore: param = backup, sharpness = ||sam_grad - normal_grad||
235	template <typename ParamT>
236	__global__ void sg11_sharpness_restore_kernel(
237	    ParamT* param, float* sharpness, const ParamT* backup,
238	    const ParamT* sam_grad, const ParamT* normal_grad, int64_t N
239	) {
240	    const int64_t stride = prim::grid_stride();
241	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
242	        param[i] = backup[i];
243	        float sg = static_cast<float>(sam_grad[i]);
244	        float ng = static_cast<float>(normal_grad[i]);
245	        float diff = sg - ng;
246	        sharpness[i] = diff * diff;
247	    }
248	}
249	
250	void launch_sg11_sharpness_restore(
251	    torch::Tensor param, torch::Tensor sharpness, torch::Tensor backup,
252	    torch::Tensor sam_grad, torch::Tensor normal_grad
253	) {
254	    const int64_t N = param.numel();
255	    if (N == 0) return;
256	    auto stream = at::cuda::getCurrentCUDAStream().stream();
257	    const int block = SG_TUNED_BLOCK_SIZE;
258	    const int grid = static_cast<int>(
259	        std::min<int64_t>(65535, (N + block - 1) / block));
260	    AT_DISPATCH_FLOATING_TYPES_AND2(
261	        at::ScalarType::Half, at::ScalarType::BFloat16,
262	        param.scalar_type(), "sg11_sharpness_restore", [&] {
263	            sg11_sharpness_restore_kernel<scalar_t>
264	                <<<grid, block, 0, stream>>>(
265	                param.data_ptr<scalar_t>(),
266	                sharpness.data_ptr<float>(),
267	                backup.data_ptr<scalar_t>(),
268	                sam_grad.data_ptr<scalar_t>(),
269	                normal_grad.data_ptr<scalar_t>(), N);
270	            SG_LAUNCH_CHECK(stream);
271	        });
272	}
273	
274	// Cosine gate: cos_sim(smart_grad, mu) clamped to [0,1].
275	float compute_cosine_gate_fused(
276	    torch::Tensor smart_grad, torch::Tensor mu, float gate_temp
277	) {
278	    auto sg_f = smart_grad.to(torch::kFloat32).flatten();
279	    auto mu_f = mu.to(torch::kFloat32).flatten();
280	    float num = (sg_f * mu_f).sum().item<float>();
281	    float den_g = (sg_f * sg_f).sum().item<float>();
282	    float den_m = (mu_f * mu_f).sum().item<float>();
283	    float denom = sqrtf(den_g * den_m + 1e-12f);
284	    float gate = (denom > 0.0f) ? (num / denom) : 0.0f;
285	    return fminf(fmaxf(gate, 0.0f), 1.0f);
286	}
