18	// Algorithm: csrc/algorithms/supergrok15.h
19	//
20	// Same two-sweep pattern as v1.1, but the gate is a global sigmoid of
21	// training accuracy (passed in as gate_global), and per-coord alpha is
22	// computed from mu via sg15_alpha_per_coord.
