356	// ── Muon (STAGED grid-cooperative Newton-Schulz) per-matrix scratch. IDENTICAL in
357	//    shape to the vit twin (vit_tc_muon_floats): the NS chain runs ONE 2D weight at
358	//    a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D weight
359	//    + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
360	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
361	//    (st.exp_avg). Largest decoder 2D weight: ff.0/ff.2 = 512×128 = 65536 numel; largest
362	//    rows = 512 ⇒ A = 512×512 (dectc::kDecMuonMaxNumel/kDecMuonMaxRows). Carved
363	//    UNCONDITIONALLY (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic
364	//    launcher (dec_tc_launcher_scratch) fits every OptId; unused by every non-Muon cell
365	//    (its P2.7/P3-2D branches are if-constexpr'd out → byte-identical). ──
366	__host__ __device__ __forceinline__ int64_t dec_tc_muon_floats(int nCTA) {
367	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
368	    return (int64_t)4 * dectc::kDecMuonMaxNumel
369	         + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows
370	         + nCTA + 1;
371	}
372	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
373	    return dec_tc_acts_floats(T, B)
374	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
375	         + (int64_t)nCTA * dectc::kLnVecElems
376	         + nCTA + 1
377	         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
378	         + dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
379	         + dec_tc_muon_floats(nCTA);          // STAGED-opt (Muon) NS per-matrix scratch
380	}
