382	template <OptId Opt>
383	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
384	fused_decoder_megakernel_tc(PersistentContext ctx,
385	                            float* __restrict__ params,
386	                            DecoderTokenCtx tok,
387	                            float* __restrict__ grad,
388	                            float lr, int step, FusedOptState st) {
389	    __shared__ DecTcSmem sm;
390	    GridBarrier bar = ctx.barrier();
391	    const int cta = blockIdx.x;
392	    const int nCTA = (int)ctx.n_ctas;
393	    const int B = tok.B;
394	    const int T = B * dec::kSeq;
395	
396	    // Workspace partition.
397	    float* ws = tok.workspace;
398	    const int64_t acts_f = dec_tc_acts_floats(T, B);
399	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
400	    float* scratch_base = ws + acts_f;
401	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
402	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
403	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
404	    float* loss_out   = loss_part + nCTA;
405	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
406	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
407	    float* dw_part    = loss_out + 1;
408	    const int kDwG    = dectc::kDecDwSplitK;
409	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
410	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
411	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
412	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
413	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
414	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
415	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
416	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
417	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
418	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
419	
420	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
421	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
422	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
423	
424	    DecWeights w = dec_bind(params);
425	
426	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
427	    //    written-once → no pre-zero). ──
428	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
429	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
430	    bar.sync();   // B0
431	
432	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
433	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
434	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
435	    const int nrows_tile = dectc::kTileM;
436	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
437	    float nll_acc = 0.0f;
438	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
439	        const int g0 = ti * nrows_tile;
440	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
441	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
442	                                              sm.sA, sm.sB, sm.red);
443	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
444	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
445	        if (threadIdx.x == 0) nll_acc += nll;
446	        __syncthreads();
447	    }
448	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
449	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
450	
451	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
452	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
453	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
454	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
455	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
456	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
457	    __syncthreads();
458	    dectc::DecDwSpec* spec = sm.spec;
459	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
460	    if (kDwG > 1) {
461	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
462	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
463	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
464	            const int gt = item / kDwG, kc = item % kDwG;
465	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
466	        }
467	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
468	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
469	    } else {
470	        for (int gt = cta; gt < n_dw; gt += nCTA)
471	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
472	    }
473	    dectc::dectc_dw_biases(spec, grad);
474	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
475	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
476	    // Loss reduce (fp64) by CTA 0.
477	    if (cta == 0 && threadIdx.x == 0) {
478	        double s = 0.0;
479	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
480	        *tok.loss_out = (float)(s / (double)B);
481	    }
482	    (void)loss_out;
483	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
484	
485	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
486	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
487	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
488	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
489	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
490	    //    deterministic ascending reduction (no float atomics): each CTA sums a
491	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
492	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
493	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
494	    //    + the eager-side clip must both see the unclipped reduced grad); the
495	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
496	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
497	    if constexpr (Opt == OptId::GrokAdamW) {
498	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
499	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
500	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
501	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
502	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
503	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
504	        const int64_t total = kDecTotalElems;
505	        const int64_t base = total / nCTA, rem = total % nCTA;
506	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
507	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
508	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
509	        float tsum = 0.0f;
510	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
511	            const float gv = grad[e0 + i];
512	            tsum += gv * gv;
513	        }
514	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
515	        float* red = sm.red;
516	        red[threadIdx.x] = tsum;
517	        __syncthreads();
518	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
519	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
520	            __syncthreads();
521	        }
522	        if (threadIdx.x == 0) sq_part[cta] = red[0];
523	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
524	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
525	        if (cta == 0 && threadIdx.x == 0) {
526	            double ss = 0.0;
527	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
528	            const float total_norm = sqrtf((float)ss);
529	            float coef = 1.0f;
530	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
531	                coef = st.grad_clip / (total_norm + 1e-6f);
532	            *coef_bc = coef;
533	        }
534	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
535	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
536	    }
537	
538	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. The apply tail
539	    //    (apply_optimizer<Prodigy>) reads st.d_factor (the effective LR scale d),
540	    //    a GLOBAL reduction over EVERY element of EVERY tensor. We compute it here,
541	    //    BYTE-FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh:465-
542	    //    544, the order prodigy.py → _ops.prodigy_fused_step actually executes):
543	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state
544	    //                slot would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits
545	    //                _d_lr=d0=1e-6, so seed it here, the grokfast-style step-1 fix)
546	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
547	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
548	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
549	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
550	    //    DETERMINISM (COMPONENT_CONTRACT): NO float atomic. Each CTA publishes its
551	    //    (r,s) into per-CTA slots (opt_reduce) → grid barrier → CTA0 owner-sums in
552	    //    ascending index order → writes d back to the persisted slot + a broadcast
553	    //    slot. The decay is on the persisted SCALARS (not the per-CTA partials):
554	    //    the work-steal queue reassigns tensors to CTAs across steps, so a per-CTA
555	    //    EMA is undefined — the live form is a scalar EMA (prodigy_sm90.cuh:488).
556	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
557	    if constexpr (Opt == OptId::Prodigy) {
558	        PrecomputeWorkspace pw{};
559	        pw.prodigy_partials = opt_reduce;            // [r slots | s slots]
560	        pw.prodigy_d        = opt_reduce + 2 * nCTA; // reduced-d broadcast slot
561	        // d_prev: persisted d_lr (slot 2 of prodigy_persist), or d0 at step 1.
562	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
563	        st.d_factor = d_prev;   // phaseA reads st.d_factor as d_prev (prodigy.h)
564	        // Phase A: each CTA accumulates Σ d_prev²·<g,p0−p> / Σ d_prev²·|g| over its
565	        // claimed tensors → per-CTA (r,s) slots. Drains the task queue (the P3
566	        // re-drain below needs a queue reset, done at the barrier).
567	        prodigy_precompute_reduce_phaseA(ctx, params, st.param_init, grad,
568	                                         kDecSizes, kDecOffsets, d_prev, pw);
569	        bar.sync_reset(ctx.g_next_task);   // B2.6a: slots published; reset queue for P3
570	        // Owner block (CTA0 thread0): EMA decay + accumulate + d_coef + update_d,
571	        // byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
572	        if (cta == 0 && threadIdx.x == 0) {
573	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
574	            for (int c = 0; c < nCTA; ++c) {
575	                r_step += pw.prodigy_partials[c];
576	                s_step += pw.prodigy_partials[nCTA + c];
577	            }
578	            // Decay persisted scalars by beta3, then add this step's reduction.
579	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
580	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
581	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
582	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
583	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
584	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
585	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
586	            st.prodigy_persist[1] = s_ema;
587	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
588	            pw.prodigy_d[0]       = d_new;          // broadcast to all CTAs
589	        }
590	        bar.sync();   // B2.6b: d visible to every CTA before the apply
591	        st.d_factor = pw.prodigy_d[0];              // the reduced d the tail reads
592	    }
593	
594	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
595	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
596	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
597	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
598	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
599	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
600	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
601	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
602	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
603	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
604	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
605	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
606	    //    muon_update_step); the matmuls are the cited new device code (the eager path
607	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
608	    //    (no extra barriers / work).
609	    if constexpr (Opt == OptId::Muon) {
610	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
611	        PrecomputeWorkspace pw{};
612	        pw.muon_X            = muon_base;
613	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
614	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
615	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
616	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
617	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
618	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
619	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
620	        const int   ns_steps = 5;                 // bindings.cpp default
621	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
622	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
623	            const int rows = M.rows, cols = M.cols;
624	            const int64_t numel = (int64_t)rows * cols;
625	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
626	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
627	            pw.muon_buf = st.exp_avg + off;
628	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
629	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
630	            bar.sync();
631	            muon_norm_reduce_phaseB(ctx, pw);
632	            bar.sync();
633	            muon_scale_X(numel, pw);
634	            bar.sync();
635	            // NS iterations. After each combine, orth holds the new iterate; swap so
636	            // the next iteration reads it as X. ns_steps swaps → final result is in
637	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
638	            for (int s = 0; s < ns_steps; ++s) {
639	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
640	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
641	                bar.sync();
642	                // AX = A X   (M=rows,N=cols,K=rows).
643	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
644	                bar.sync();
645	                // AAX = A (AX) (M=rows,N=cols,K=rows).
646	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
647	                bar.sync();
648	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
649	                bar.sync();
650	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
651	            }
652	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
653	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
654	            const float neg_lr_scale = -lr * scale;
655	            const float decay_factor = 1.0f - lr * st.wd;
656	            float* __restrict__ p = params + off;
657	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
658	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
659	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
660	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
661	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
662	        }
663	    }
664	
665	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
666	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
667	    st.lr = lr;
668	    {
669	        __shared__ int task_slot;
670	        TaskQueue q = ctx.queue();
671	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
672	             t = q.next_block(&task_slot)) {
673	            const int n = kDecSizes[t];
674	            const int64_t off = (int64_t)kDecOffsets[t];

674	            const int64_t off = (int64_t)kDecOffsets[t];
675	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
676	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
677	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
678	            if constexpr (Opt == OptId::Muon) {
679	                if (dectc::dec_is_muon_2d(t)) continue;
680	            }
681	            FusedOptState ts = rebase_state<Opt>(st, off);
682	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
683	            //     t == the tensor's flat named_parameters() layer index (the
684	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
685	            //     enumeration order, so t IS the eager layer index). bc1 must be
686	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
687	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
688	            if constexpr (Opt == OptId::GrokAdamW) {
689	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
690	                ts.beta1 = b1;
691	                ts.bc1   = 1.0f - powf(b1, (float)step);
692	            }
693	            float* __restrict__ p = params + off;
694	            const float* __restrict__ gg = grad + off;
695	            if constexpr (Opt == OptId::Muon) {
696	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
697	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
698	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
699	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
700	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
701	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
702	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
703	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
704	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
705	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
706	                // adamw_step with the aux hyperparameters — IDENTICAL to the vit twin.
707	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
708	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
709	                for (int i = threadIdx.x; i < n; i += blockDim.x)
710	                    algo::adamw_step<float, float>(
711	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
712	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
713	                        a_bc1, a_bc2, (int64_t)i);
714	            } else {
715	                for (int i = threadIdx.x; i < n; i += blockDim.x)
716	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
717	            }
718	        }
719	    }
720	}
