722	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
723	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
724	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
725	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
726	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
727	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
728	// nCTA (the dW/embedding owner maps are functions of nCTA).
729	template <OptId Opt>
730	cudaError_t launch_fused_decoder_megakernel_tc(
731	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
732	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
733	        int ncta_cap = 0) {
734	    int dev = 0;
735	    cudaError_t err = cudaGetDevice(&dev);
736	    if (err != cudaSuccess) return err;
737	    int n_sms = 0;
738	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
739	    if (err != cudaSuccess) return err;
740	
741	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
742	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
743	    // can't place one block/SM, REFUSE (the grid barrier would hang).
744	    int occ = 0;
745	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
746	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
747	        /*dynamicSMemBytes=*/0);
748	    if (err != cudaSuccess) return err;
749	    if (occ < 1) return cudaErrorLaunchOutOfResources;
750	
751	    unsigned launch_ctas = (unsigned)n_sms;
752	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
753	    ctx.n_ctas = launch_ctas;
754	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
755	    // AND it guarantees full token tiles for the projections). NO G-divisibility
756	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
757	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
758	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
759	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
760	
761	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
762	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
763	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }

80	// OPTID-GENERIC (owner baseline directive — all 33 cells on L3-TC): the fwd+bwd+
81	// grad-reduction is OPTIMIZER-INDEPENDENT (the same validated wgmma decoder kernel);
82	// ONLY the per-element optimizer TAIL (apply_optimizer<Opt>) differs, and that tail
83	// is the 14/0-apply-parity math already in opt_components.cuh. So this launcher
84	// takes `opt_id` (the OptId int) and dispatches to the matching kernel instantiation
85	// over the SAME state buffer. The state layout is [m | v | extra] (3*total) + loss:
86	//   * lion              uses m only (v/extra unread; bound harmlessly)
87	//   * adamw             uses m, v
88	//   * grokfast/grokadamw use m, v, ema  (ema == the `extra` slice, state + 2*total)
89	//   * neuralgrok        uses m, v, AND a psi-net weight pack the cell supplies in the
90	//                       `extra` slice (kPsiPackFloats floats); st.psi_W1/b1/W2 bind
91	//                       to those offsets, exactly as opt_components.cuh documents.
92	// The STAGED optimizers prodigy (P2.6 global-d) and muon (P2.7 grid-cooperative NS)
93	// ARE routed here: their precompute is an IN-KERNEL phase, so they remain a SINGLE
94	// persistent launch (the cases below). The SAM-coupled SG11/SG15/looksam and SG2 are
95	// NOT — they need a 2nd in-kernel fwd+bwd / a sharpness ABI field / a segmented sort
96	// that this single-launch path does not carry; dispatch.cpp gates them out (and
97	// wiring_check fails them loud with the cited reason). NeuralGrok is wired but its
98	// host-trained amplifier is a separate concern (the race fn gates it).
99	//
100	// ncta_cap: forwarded to the TC launcher (0 = one CTA/SM = full saturation, the
101	// shipped config). The race always passes 0.
102	cudaError_t mega_decoder_real_adamw_tc(
103	        PersistentContext ctx, float* params,
104	        const int* tokens, const int* targets, int B,
105	        float* state, float* grad, float* /*workspace_unused*/, float* loss_out,
106	        const int* sizes, const int* offsets,
107	        float lr, int step, const FusedScalars& scalars, cudaStream_t stream,
108	        int ncta_cap, int opt_id) {
109	    (void)sizes; (void)offsets;  // TC kernel reads kDecSizes/kDecOffsets directly.
110	
111	    const int64_t total = kDecTotalElems;
112	    const int T = B * dec::kSeq;
113	
114	    int dev = 0;
115	    cudaError_t err = cudaGetDevice(&dev);
116	    if (err != cudaSuccess) return err;
117	    int n_sms = 1;
118	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
119	    if (err != cudaSuccess) return err;
120	    int nCTA = n_sms;
121	    if (ncta_cap > 0 && ncta_cap < nCTA) nCTA = ncta_cap;
122	
123	    const int64_t need = dec_tc_workspace_floats(T, B, nCTA);
124	    DecTcLauncherScratch& sc = dec_tc_launcher_scratch(dev, need);
125	
126	    // Re-point the ctx counters at THIS TU's cached counters (dispatch.cpp built
127	    // ctx pointing at its scalar DecoderScratch counters; the TC launcher zeroes
128	    // them per-launch, but they must be the ones this scratch owns so the grid
129	    // barrier is consistent with the workspace).
130	    ctx.g_next_task   = sc.g_next;
131	    ctx.g_arrived     = sc.g_arrived;
132	    ctx.g_generation  = sc.g_generation;
133	    ctx.n_tasks       = kDecNumTensors;  // parameter tensors for reduce+opt phases
134	
135	    // Bind the optimizer state slices. [m | v | extra] over the SAME state buffer;
136	    // each tail reads only its own buffers (opt_components.cuh guarantees unused
137	    // pointers are never dereferenced). ema/psi-net live in the `extra` slice.
138	    float* const m_slice     = state;
139	    float* const v_slice     = state + total;
140	    float* const extra_slice = state + 2 * total;
141	    FusedOptState st;
142	    st.exp_avg    = m_slice;
143	    st.exp_avg_sq = v_slice;
144	    st.ema        = extra_slice;          // grokfast/grokadamw slow-grad EMA
145	    // NeuralGrok psi-net pack (kPsiPackFloats floats at the head of `extra`): the
146	    // cell places [psi_W1 | psi_b1 | psi_W2 | psi_b2] there; bind the device pointers
147	    // so the apply reads real weights (psi_b2 is read on-device from psi_W2[kPsiHidden]).
148	    st.psi_W1     = extra_slice + kPsiW1Off;
149	    st.psi_b1     = extra_slice + kPsiB1Off;
150	    st.psi_W2     = extra_slice + kPsiW2Off;
151	    // PRODIGY (STAGED global-d) state bindings. The cell extends the state buffer
152	    // to [m | v | extra/s_track | loss | param_init | r_ema | s_ema | d_lr] (host
153	    // sizes it to >= 4*total + 4; see dispatch.fused_train_step). The `extra` slice
154	    // doubles as Prodigy's `s` trajectory accumulator (the apply reads st.s_track,
155	    // not st.ema — they alias here, harmless: Prodigy has no slow-grad EMA). The
156	    // trajectory anchor p0 (param_init) follows the loss slot; the 3 persisted
157	    // estimator scalars [r_ema | s_ema | d_lr] follow param_init. loss_out points at
158	    // state+3*total (dispatch's loss_slot), so param_init = loss_out + 1.
159	    st.s_track        = extra_slice;            // Prodigy `s` (per-element accumulator)
160	    st.param_init     = loss_out + 1;           // state + 3*total + 1
161	    st.prodigy_persist = loss_out + 1 + total;  // [r_ema | s_ema | d_lr]
162	    apply_scalars(st, scalars);   // FULL scalar set (un-frozen bc1/bc2/... + d0/d_coef/beta3)
163	    st.lr = lr;
164	
165	    DecoderTokenCtx tok;
166	    tok.tokens    = tokens;
167	    tok.targets   = targets;
168	    tok.B         = B;
169	    tok.workspace = sc.workspace;
170	    tok.loss_out  = loss_out;
171	
172	    // Dispatch to the matching kernel instantiation. The fwd+bwd is identical across
173	    // these OptIds; the template differs ONLY in the P3 apply_optimizer<Opt> tail.
174	    // Unsupported opt_ids return cudaErrorInvalidValue → dispatch.cpp throws LOUD (no
175	    // silent scalar/adamw fallback — the no-suppression rule). The STAGED/model-coupled
176	    // optimizers are intentionally NOT cases here (they cannot run as a single launch).
177	    switch (static_cast<OptId>(opt_id)) {
178	        case OptId::AdamW:
179	            return launch_fused_decoder_megakernel_tc<OptId::AdamW>(
180	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
181	        case OptId::Lion:
182	            return launch_fused_decoder_megakernel_tc<OptId::Lion>(
183	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
184	        case OptId::Grokfast:
185	            return launch_fused_decoder_megakernel_tc<OptId::Grokfast>(
186	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
187	        case OptId::GrokAdamW:
188	            return launch_fused_decoder_megakernel_tc<OptId::GrokAdamW>(
189	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
190	        case OptId::NeuralGrok:
191	            return launch_fused_decoder_megakernel_tc<OptId::NeuralGrok>(
192	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
193	        case OptId::Prodigy:
194	            // STAGED global-d: the SAME single persistent launch — the d-estimate
195	            // cross-tensor reduction is an IN-KERNEL phase (P2.6, between B2 and P3),
196	            // not a separate launch. st carries param_init/prodigy_persist/d0/d_coef/
197	            // beta3; the kernel decays+accumulates the EMA, updates d, applies.
198	            return launch_fused_decoder_megakernel_tc<OptId::Prodigy>(
199	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
200	        case OptId::Muon:
201	            // STAGED grid-cooperative Newton-Schulz (wave-2 decoder lane): the SAME
202	            // single persistent launch — the NS orthogonalization of the 11 2D weights
203	            // (tok/pos/in_proj/out_proj/ff.0/ff.2/out) is an IN-KERNEL phase (P2.7,
204	            // between B2/P2.6 and P3), grid-barrier-looped per matrix, NOT a separate
205	            // launch. The per-matrix NS scratch lives in the workspace (dec_tc_muon_floats,
206	            // carved after the Prodigy reduce slots). The persistent momentum buffer is
207	            // the m-slice (st.exp_avg); the 1D/non-2D weights take the AdamW tail in P3
208	            // reading the INDEPENDENT aux_lr/aux_betas (eager Muon adamw_* group). The
209	            // vit twin (mega_vit_real_adamw_tc_launcher.cu) proved this routing.

672	__device__ float dectc_forward_tile(
673	        const DecWeights& w, int g0, int nrows, const DecActs& acts,
674	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
675	        const int* __restrict__ tgt_ids,
676	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
677	    const int nsamp = nrows / dec::kSeq;
678	    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
679	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
680	        const int r = idx / dec::kD, j = idx % dec::kD;
681	        const int g = g0 + r;
682	        const int tid = tok_ids[g];
683	        const int sp = g % dec::kSeq;            // position within the sample
684	        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
685	        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
686	    }
687	    __syncthreads();
688	
689	    for (int li = 0; li < dec::kLayers; ++li) {
690	        const DecWeights::Layer& L = w.layer[li];
691	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
692	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
693	        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, L.in_w, sc.qkv[li], dec::kD, 3 * dec::kD, sA, sB);
694	        __syncthreads();
695	        // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
696	        // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
697	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x) {
698	            const int j = idx % (3 * dec::kD);
699	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
700	            sc.qkv[li][idx] = __float2bfloat16(v);
701	        }
702	        __syncthreads();
703	        // attention → ctx (work fp32) + attn[li] weights.
704	        dectc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
705	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
706	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
707	            const int r = idx / dec::kD, j = idx % dec::kD;
708	            acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.work[(int64_t)r * dec::kD + j]);
709	        }
710	        __syncthreads();
711	        // a = X_ctx @ out_w^T (+ out_b)  (N=d, K=d). fp32 → work.

898	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
899	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
900	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
901	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
902	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
903	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
904	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
905	//
906	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
907	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
908	//  is the dedicated scratch.dh.
909	// ════════════════════════════════════════════════════════════════════════
910	__device__ void dectc_backward_tile(
911	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
912	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
913	        float* __restrict__ lnvec, float* __restrict__ work2,
914	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
915	    const int nsamp = nrows / dec::kSeq;
916	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
917	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
918	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
919	    for (int li = 0; li < dec::kLayers; ++li) {
920	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
921	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
922	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
923	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
924	    }
925	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
926	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
927	
928	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
929	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
930	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
931	    // First zero scratch.dh for the whole tile (only last positions get grad).
932	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
